from lib import *
S = SS('w36')
steps = [
    step("STUN 报文:请求只有 20 字节的头——类型 0x0001(Binding Request)、长度 0、magic cookie 0x2112a442、12 字节的随机事务编号。应答 68 字节:类型 0x0101(Binding Success Response)、长度 48、事务编号与请求相同。服务器 2 的应答属性是 XOR-MAPPED-ADDRESS(8 字节)、旧式的 MAPPED-ADDRESS(8 字节)、SOFTWARE(20 字节);服务器 3 的是 MAPPED-ADDRESS、RESPONSE-ORIGIN、OTHER-ADDRESS(各 8 字节)和 XOR-MAPPED-ADDRESS。XOR-MAPPED-ADDRESS 的值 8 字节:保留 1 + 地址族 1(IPv4)+ 端口 2 + 地址 4。线上的端口字段 0xe418 与 cookie 高 16 位 0x2112 异或得 50442,正是我的本地端口 50442(NAT 没改端口);旧式 MAPPED-ADDRESS(不异或)与异或还原出来的地址和端口一致——异或是为了躲开会改写载荷里 IP 地址的 NAT。抓包:4 个 IP 包,请求 IP 总长 48 字节(20 IP + 8 UDP + 20 STUN),应答 48 和 96 字节;RTT 服务器 2 是 207 ms,服务器 3 是 8 ms。", t=tl(S(1)), mark=lidx(S(1), '请求(20 字节)', 'XOR-MAPPED-ADDRESS 的值', '同一个应答里还有旧式'), done=lidx(S(1), '服务器 2的应答', '服务器 3的应答', '抓包:4 个 IP 包'), b=bars([['请求 STUN 部分', 20, '20 字节'], ['应答 STUN 部分', 68, '68 字节'], ['XOR-MAPPED-ADDRESS 值', 8, '8 字节']], 68, mark=[2], done=[0, 1]), kv=KV([['请求', '20 字节:类型 · 长度 · cookie · 事务编号'], ['应答', '68 字节,带 XOR-MAPPED-ADDRESS 等属性'], ['XOR', '端口 ^ 0x2112,地址 ^ cookie'], ['本机端口', '50442 = 外部端口(NAT 没改)']], ['XOR'])),
    step("映射行为(RFC 5780):同一个本地套接字依次发往服务器的 4 个“目的”——主 IP:主端口、主 IP:另一个端口、另一个 IP:主端口、另一个 IP:另一个端口。能做这个测试的服务器要通告 OTHER-ADDRESS,4 个服务器里只有服务器 3 和 4 通告了(服务器 1、2 不通告)。服务器 3 的测试:本地端口 52182,4 个目的看到的外部端口都是 52182,公网地址一致;服务器 4:本地端口 55093,4 个外部端口都是 55093,公网地址一致。结论:本机出口的 NAT 是“与目的无关的映射”(EIM),无论发给哪个 IP 或端口,外部地址和端口都不变——这是 UDP 打洞能成功的前提(第 19 篇用 3 个服务器和 40 个套接字得到过类似结论)。", t=tl(S(2)), mark=lidx(S(2), '服务器 3(本地端口', '服务器 4(本地端口'), done=lidx(S(2), '服务器 1:不通告', '服务器 2:不通告'), b=bars([['服务器 3 · 4 个目的的外部端口都是', 52182, '52182'], ['服务器 4 · 4 个目的的外部端口都是', 55093, '55093']], 55093, mark=[0, 1], done=[]), kv=KV([['测试', '同一个套接字发往 4 个不同的目的'], ['服务器 3 / 4', '外部端口始终等于本地端口'], ['结论', '与目的无关的映射(EIM)']], ['结论'])),
    step("过滤行为(RFC 5780):先向服务器发一个请求(给服务器开个洞),再让服务器用“另一个 IP 和端口”(CHANGE-REQUEST 0x06)或“同 IP 另一个端口”(0x02)回应,看能不能收到。服务器 3 和 4 两种都没收到——既可能是本机 NAT 的过滤规则挡住了,也可能是这些服务器根本没实现 CHANGE-REQUEST,这里无法区分。公共 STUN 服务器大多不再实现 CHANGE-REQUEST(RFC 5780 把这套测试标成可选)。所以本机 NAT 的映射行为测出来了(与目的无关),过滤行为没有测出来;不能因为“两种都没收到”就说是端口受限,只有收到了换 IP 的应答才能确定是全锥。", t=tl(S(3)), mark=lidx(S(3), '服务器 3:CHANGE-REQUEST', '服务器 4:CHANGE-REQUEST', '本机的 NAT'), done=lidx(S(3), '服务器 1:不通告', '服务器 2:不通告'), kv=KV([['CHANGE-REQUEST 0x06 / 0x02', '两种都没收到'], ['原因', 'NAT 挡住?服务器没实现?无法区分'], ['结论', '过滤行为本次没测出']], ['结论'])),
    step("STUN 自己的可靠性:跑在 UDP 上,客户端按 RFC 5389 重传(这是计算):初始 RTO 500 ms,每次翻倍,最多发 7 次,发出时刻是 0、0.5、1.5、3.5、7.5、15.5、31.5 秒,第 7 次发出后再等 16 × 500 ms = 8 秒才放弃,总共 39.5 秒。实测 4 个服务器各发 8 个请求都全部收到应答:服务器 1 的 RTT 中位 204 ms(最小 203、最大 206),服务器 2 是 187 ms(185~233),服务器 3 是 6 ms(5~13),服务器 4 是 101 ms(94~103)——RTT 差别主要来自服务器离本机有多远。", t=tl(S(4)), mark=lidx(S(4), '重传时刻'), done=lidx(S(4), '服务器 1:8 个请求', '服务器 2:8 个请求', '服务器 3:8 个请求', '服务器 4:8 个请求'), b=bars([['服务器 1 · RTT 中位', 204, '204 ms'], ['服务器 2 · RTT 中位', 187, '187 ms'], ['服务器 3 · RTT 中位', 6, '6 ms'], ['服务器 4 · RTT 中位', 101, '101 ms']], 204, mark=[2], done=[0, 1, 3]), kv=KV([['重传', '0、0.5、1.5、3.5、7.5、15.5、31.5 秒'], ['放弃', '最后再等 8 秒,共 39.5 秒'], ['实测', '4 个服务器 8 / 8 都有应答']], ['重传'])),
    step("UDP 打洞的原理(模拟,不是实测):两个内网主机 A、B 各在一个 NAT 后面,都先向公网的会合服务器 S 发 UDP,S 把各自观察到的外部地址告诉对方,然后两边同时向对方的外部地址发包。我把 NAT 按“映射 + 过滤”分成四种:全锥(EIM / 无过滤)、地址受限、端口受限、对称(每个目的分配不同外部端口 + 严格过滤),两两组合模拟。结果:16 种组合里 13 种能打通,打不通的是“对称 + 端口受限”(两个方向)和“对称 + 对称”——对称 NAT 给发往对方的包分配了和发往 S 时不同的外部端口,对方按 S 看到的端口去发,过滤规则不认。这类情况只能走中继服务器(TURN)。本机实测的映射行为是与目的无关,所以至少在映射这一点上不是对称 NAT。", t=tl(S(5)), mark=lidx(S(5), '对称        通', '端口受限      通'), done=lidx(S(5), 'A \\\\ B', '全锥        通', '地址受限      通', '16 种组合里'), b=bars([['能打通的组合', 13, '13 / 16'], ['打不通的组合', 3, '3 / 16']], 16, mark=[1], done=[0]), kv=KV([['全锥 · 地址受限', '与任何类型都能打通'], ['端口受限 ↔ 对称', '打不通'], ['对称 ↔ 对称', '打不通,走 TURN 中继'], ['依据', '纸面模拟,不是实测']], ['依据'])),
]
A = mkartw('w36', 36, '网络协议,STUN,NAT穿透,UDP打洞,RFC5780,真实验证,动画演示',
    '解码真实 STUN 报文(请求 20 字节,XOR-MAPPED-ADDRESS 端口异或 0x2112 还原出本地端口);用 RFC 5780 测出本机 NAT 是与目的无关的映射,但过滤行为公共服务器测不出;STUN 重传按 RFC 共 39.5 秒;UDP 打洞模拟矩阵 16 种组合 13 种能通。',
    'STUN 到底是个什么协议?为什么两个都躲在 NAT 后面的设备还能直连?哪些情况打不通?这篇解码真实的 STUN 请求和应答,用 RFC 5780 的方法测本机 NAT 的映射行为,并用一个小模拟推演打洞在四种 NAT 之间的成败。',
    [('20 字节', 'STUN 请求的大小:类型、长度、magic cookie、96 位事务编号'), ('13 / 16', '模拟里四种 NAT 两两组合 UDP 打洞能成功的组合数(失败的 3 种都涉及对称 NAT)'), ('EIM', '本机出口 NAT 的映射行为:发往 4 个不同目的的外部端口都不变,打洞的前提')],
    [('STUN 报文', '<p>20 字节头加属性。应答里的 XOR-MAPPED-ADDRESS 把端口和地址与 magic cookie 异或,避免被改写载荷的 NAT 破坏;还原后得到 NAT 为这次连接分配的外部地址和端口。</p>'),
     ('映射行为', '<p>用 OTHER-ADDRESS 向同一服务器的另一个 IP / 端口发请求,外部端口不变就是与目的无关的映射(EIM)。本机测出来是 EIM。</p>'),
     ('过滤行为', '<p>要靠 CHANGE-REQUEST 让服务器换 IP / 端口回应。实测公共服务器没有回应,分不清是 NAT 过滤还是服务器没实现,所以本机的过滤行为没有确定。</p>'),
     ('可靠性', '<p>STUN 在 UDP 上用 500 ms 起翻倍的 RTO 重传,最多 7 次,总共 39.5 秒。</p>'),
     ('打洞', '<p>两边各向会合服务器报到,交换外部地址后同时发包。除了涉及对称 NAT 的几种组合外都能打通,打不通就要走 TURN 中继。</p>')],
    steps,
    [ENV_W + '。第一至四节是真实的公网 STUN 服务器(Cloudflare、Twilio、小米、sipgate),本机出口的公网地址不写出,只比较是否相同;第五节是纸面模拟,地址为文档地址',
     '没有验证:本机 NAT 的过滤行为(服务器不支持 CHANGE-REQUEST);真实的 UDP 打洞(需要第二台 NAT 后面的主机和会合服务器);TURN / ICE 的完整流程;对称 NAT 下端口预测的可行性;映射的超时时间'],
    'STUN 与 NAT 穿透')
